xml.Script:
//        include 'Figures\Scripts\Cube_Standard_Colors.inc';

        W := 0.5;
        D := W * 0.1;
        sAngle := 2 * Pi / 3;

        // small parts
        sProfile := '97,36, 97,56, 84,59, 74,65, 65,74, 59,84, 56,95, 55,105, 56,115, 59,126, 65,136, 74,145, 84,151, 94,154, 105,155, 115,154, 126,151, 136,145, 145,136, 151,126, 154,115, 155,105, 154,95, 151,84, 145,74, 136,65, 126,59, 113,56, 113,36, 105,35';
        ProfileSize := 210;

        function GetInt(): integer;
        begin
          p := Pos(',', sProfile);
          if p = 0 then begin
            substr := sProfile;
            sProfile := '';
          end else begin
            substr := copy(sProfile, 1, p-1);
            Delete(sProfile, 1, p);
          end;
          Result := StrToInt(Trim(substr));
        end;

        pCount := 0;
        while Length(sProfile) > 0 do begin
          SPx[pCount] := 1.001;
          SPy[pCount] := -(GetInt / ProfileSize - 0.5) * W;
          SPz[pCount] := (GetInt / ProfileSize - 0.5) * W;
          Inc(pCount);
        end;

        procedure CalcVectors();
        begin
            for i := 0 to pCount - 1 do begin
                Vx[i] := Cx[c1]*SPx[i] + Cx[c2]*SPy[i] + Cx[c3]*SPz[i];
                Vy[i] := Cy[c1]*SPx[i] + Cy[c2]*SPy[i] + Cy[c3]*SPz[i];
                Vz[i] := Cz[c1]*SPx[i] + Cz[c2]*SPy[i] + Cz[c3]*SPz[i];
            end;
        end;

        function FromTo(iFrom, iTo);
        begin
            Result := IntToStr(iFrom);
            for i := iFrom + 1 to iTo do
                Result := Result + ';' + IntToStr(i);
        end;

        s3 := sqrt(3);
        Kp := 0.32;
        Cx[4] := s3 * Kp; Cy[4] := -s3 * Kp; Cz[4] := 0;
        Cx[5] := Kp; Cy[5] := Kp; Cz[5] := -2 * Kp;
